"use client";

import { motion, useReducedMotion, type Transition } from "motion/react";
import { type ComponentPropsWithoutRef, type KeyboardEvent, useEffect, useId, useRef, useState } from "react";

import { cn } from "@/lib/utils";

/** One row of the wheel. `value` is what the picker reports; `label` is what the person reads. */
export type WheelOption = { value: string; label: string };

/** Props for a wheel picker. Pass `value` to control it, or `defaultValue` to let it hold its own state. */
export type WheelPickerProps = Omit<ComponentPropsWithoutRef<"div">, "onChange" | "children" | "defaultValue"> & {
  options: WheelOption[];
  value?: string;
  /** Defaults to the first option. */
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  disabled?: boolean;
};

// Rows fade and shrink by their distance from the centre row: the selected row, its neighbours, the rest.
const OPACITY = [1, 0.6, 0.35];
const SCALE = [1, 0.9, 0.8];
const SETTLE: Transition = { duration: 0.15, ease: [0.165, 0.84, 0.44, 1] };
const INSTANT: Transition = { duration: 0 };

function rowHeightOf(area: HTMLElement | null) {
  const row = area?.firstElementChild;
  return row instanceof HTMLElement ? row.offsetHeight : 0;
}

/**
 * Picks one option from a vertical wheel, such as an hour or a duration. The wheel is a native scroll area
 * with scroll snapping, so a flick keeps its momentum and the nearest option lands in the centre. Give it an
 * `aria-label` or `aria-labelledby`.
 */
export function WheelPicker({
  options,
  value,
  defaultValue,
  onValueChange,
  disabled = false,
  className,
  onKeyDown,
  ...divProps
}: WheelPickerProps) {
  const [ownValue, setOwnValue] = useState(defaultValue ?? options[0]?.value);
  const scroller = useRef<HTMLDivElement>(null);
  // The row a scroll we started is heading to. Rows it passes on the way are not selections.
  const target = useRef<number | null>(null);
  const placed = useRef(false);
  const id = useId();
  const reduceMotion = useReducedMotion();
  const selected = Math.max(0, options.findIndex((option) => option.value === (value ?? ownValue)));

  const select = (index: number) => {
    const next = options[Math.min(options.length - 1, Math.max(0, index))];
    if (!next || next.value === options[selected]?.value) return;
    if (value === undefined) setOwnValue(next.value);
    onValueChange?.(next.value);
  };

  // Bring the selected row to the centre when the value changes from outside the scroll:
  // on mount, on a key press, on a click, or when the parent sets a new value.
  useEffect(() => {
    const area = scroller.current;
    const height = rowHeightOf(area);
    if (!area || height === 0) return;
    if (Math.round(area.scrollTop / height) !== selected) {
      target.current = selected;
      // The first placement jumps: the wheel must not spin when the page opens.
      area.scrollTo?.({ top: selected * height, behavior: placed.current && !reduceMotion ? "smooth" : "auto" });
    }
    placed.current = true;
  }, [selected, reduceMotion]);

  const handleScroll = () => {
    const height = rowHeightOf(scroller.current);
    if (!scroller.current || height === 0) return;
    const centred = Math.round(scroller.current.scrollTop / height);
    if (target.current !== null) {
      if (centred === target.current) target.current = null;
      return;
    }
    select(centred);
  };

  const handleKeyDown = (event: KeyboardEvent<HTMLDivElement>) => {
    onKeyDown?.(event);
    if (event.defaultPrevented || disabled) return;
    const moves = new Map([
      ["ArrowDown", selected + 1],
      ["ArrowUp", selected - 1],
      ["Home", 0],
      ["End", options.length - 1],
    ]);
    const next = moves.get(event.key);
    if (next === undefined) return;
    event.preventDefault();
    select(next);
  };

  // The person took the wheel back, so the scroll position decides again.
  const release = () => {
    target.current = null;
  };

  return (
    <div
      {...divProps}
      role="listbox"
      aria-orientation="vertical"
      aria-activedescendant={options[selected] ? `${id}-${selected}` : undefined}
      aria-disabled={disabled || undefined}
      tabIndex={disabled ? -1 : 0}
      onKeyDown={handleKeyDown}
      className={cn(
        // Three rows of 44px show; the selected one sits in the middle.
        "relative h-33 w-24 shrink-0 overflow-hidden rounded-xl border border-border bg-card text-sm text-foreground outline-none",
        "focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
        disabled && "pointer-events-none opacity-50",
        className,
      )}
    >
      <span aria-hidden="true" className="pointer-events-none absolute inset-x-1 top-1/2 h-11 -translate-y-1/2 rounded-lg bg-muted" />
      <div
        ref={scroller}
        role="presentation"
        // A scroll area with nothing focusable inside becomes a tab stop of its own. The listbox is the one stop.
        tabIndex={-1}
        onScroll={handleScroll}
        onPointerDown={release}
        onWheel={release}
        onTouchStart={release}
        // One row of padding above and below lets the first and last rows reach the centre.
        className="relative h-full snap-y snap-mandatory overflow-y-auto overscroll-contain py-11 outline-none [scrollbar-width:none]"
      >
        {options.map((option, index) => {
          const distance = Math.min(2, Math.abs(index - selected));
          return (
            <div
              key={option.value}
              id={`${id}-${index}`}
              role="option"
              aria-selected={index === selected}
              onClick={() => select(index)}
              className={cn(
                "flex h-11 cursor-pointer snap-center items-center justify-center tabular-nums",
                index === selected && "font-semibold",
              )}
            >
              {/* The label shrinks, not the row, so each row keeps its 44px tap height. */}
              <motion.span
                className="inline-block"
                initial={false}
                // Reduced motion keeps the fade, which marks the selection, and drops the shrink.
                animate={{ opacity: OPACITY[distance], scale: reduceMotion ? 1 : SCALE[distance] }}
                transition={reduceMotion ? INSTANT : SETTLE}
              >
                {option.label}
              </motion.span>
            </div>
          );
        })}
      </div>
      {/* A row that scrolls past the top or the bottom fades out, so it is never cut by the edge. */}
      <span aria-hidden="true" className="pointer-events-none absolute inset-x-0 top-0 h-4 bg-linear-to-b from-card to-transparent" />
      <span aria-hidden="true" className="pointer-events-none absolute inset-x-0 bottom-0 h-4 bg-linear-to-t from-card to-transparent" />
    </div>
  );
}
